<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { showToast, watchToast } from './toast';
type Item = { id:number; name:string; status:'active'|'inactive'; description?:string; merchant_id?:number; category_id?:number|null; price?:string };
const props = defineProps<{ kind:'merchant'|'product'; token:string }>();
const items=ref<Item[]>([]), loading=ref(false), error=ref(''), saving=ref(false), offset=ref(0), hasNext=ref(false), showForm=ref(false), editing=ref<Item|null>(null);
watchToast(error, 'error');
const selectedId=ref<number|null>(null), queryId=ref(''), queried=ref(false);
const selected=computed(()=>items.value.find(item=>item.id===selectedId.value));
const form=ref({name:'',description:'',status:'active',merchant_id:'',category_id:'',price:''});
const title=computed(()=>props.kind==='merchant'?'商户':'商品');
const endpoint=computed(()=>props.kind==='merchant'?'/merchants':'/products');
async function api(path:string, method='GET', body?:unknown) {
  let response:Response;
  try { response=await fetch('/api/v1'+path,{method,headers:{Authorization:`Bearer ${props.token}`,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)}); } catch { throw new Error('无法连接服务，请检查后端是否启动。'); }
  if(!response.ok){const data=await response.json().catch(()=>({})); throw new Error(typeof data.detail==='string'?data.detail:'操作失败，请检查输入后重试。');}
  return response.status===204?null:response.json();
}
async function load(){loading.value=true;error.value='';selectedId.value=null;try{const data:Item[]=await api(`${endpoint.value}?offset=${offset.value}&limit=21`);items.value=data.slice(0,20);hasNext.value=data.length>20;queried.value=false;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
watch(()=>props.kind,()=>{offset.value=0;queryId.value='';showForm.value=false;void load();},{immediate:true});
function open(item?:Item){editing.value=item||null;form.value={name:item?.name||'',description:item?.description||'',status:item?.status||'active',merchant_id:item?.merchant_id?.toString()||'',category_id:item?.category_id?.toString()||'',price:item?.price?.toString()||''};error.value='';showForm.value=true;}
async function save(){saving.value=true;error.value='';try{const name=form.value.name.trim();if(!name)throw new Error('请输入名称。');const body:Record<string,unknown>={name,status:form.value.status};if(props.kind==='merchant')body.description=form.value.description.trim();else {if(!editing.value)body.merchant_id=Number(form.value.merchant_id);body.category_id=form.value.category_id ? Number(form.value.category_id) : null;body.price=form.value.price;if((!editing.value && (!Number.isInteger(body.merchant_id)||Number(body.merchant_id)<1))||form.value.price===''||!/^\d+(\.\d{1,2})?$/.test(form.value.price))throw new Error('请输入有效的商户编号及最多两位小数的价格。');}await api(endpoint.value+(editing.value?`/${editing.value.id}`:''),editing.value?'PATCH':'POST',body);showForm.value=false;showToast('保存成功');await load();}catch(e){error.value=(e as Error).message;}finally{saving.value=false;}}
async function remove(item:Item){if(!window.confirm(`确定删除${title.value}“${item.name}”吗？此操作无法撤销。`))return;error.value='';try{await api(`${endpoint.value}/${item.id}`,'DELETE');showToast('删除成功');if(items.value.length===1&&offset.value>0)offset.value-=20;await load();}catch(e){error.value=(e as Error).message;}}
async function search(){if(!/^[1-9]\d*$/.test(queryId.value)){error.value='请输入有效的编号。';return;} loading.value=true;error.value='';selectedId.value=null;try{const item:Item=await api(`${endpoint.value}/${queryId.value}`);items.value=[item];queried.value=true;hasNext.value=false;}catch(e){items.value=[];queried.value=true;error.value=(e as Error).message;}finally{loading.value=false;}}
function refresh(){queryId.value='';offset.value=0;void load();}
function page(delta:number){offset.value+=delta*20;void load();}
</script>
<template><section class="management"><div class="filters"><label>{{ title }}编号 <input v-model.trim="queryId" inputmode="numeric" :aria-label="`${title}编号`" :placeholder="`请输入${title}编号`" @keyup.enter="search"></label><div class="filter-actions"><button class="secondary" :disabled="loading" @click="refresh">重置</button><button class="primary-btn" :disabled="loading" @click="search">搜索</button></div></div><div class="panel"><div class="toolbar"><h2>{{ title }}列表</h2><div class="toolbar-actions"><button class="icon-button" @click="refresh" :disabled="loading" title="刷新" aria-label="刷新">↻</button><button class="primary-btn" @click="open()">＋ 新增{{ title }}</button><button class="secondary" :disabled="!selected" @click="selected && remove(selected)">删除</button><button class="secondary" :disabled="!selected" @click="selected && open(selected)">修改</button></div></div><div class="table-wrap"><table><thead><tr><th>选择</th><th>编号</th><th>名称</th><th>{{ kind==='merchant'?'商户描述':'所属商户编号' }}</th><th v-if="kind==='product'">价格</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><input v-model="selectedId" type="radio" name="selected-item" :value="item.id" :aria-label="`选择${item.name}`"></td><td>{{ item.id }}</td><td class="name">{{ item.name }}</td><td>{{ kind==='merchant'?(item.description || '—'):item.merchant_id }}</td><td v-if="kind==='product'">¥ {{ Number(item.price).toFixed(2) }}</td><td><span class="status" :class="item.status">{{ item.status==='active'?'启用':'停用' }}</span></td><td><button class="link" @click="open(item)">编辑</button><button class="link danger" @click="remove(item)">删除</button></td></tr><tr v-if="!items.length"><td :colspan="kind==='product'?7:6" class="empty">{{ loading?'加载中…':error?'加载失败，请重试':'暂无数据' }}</td></tr></tbody></table></div><div class="pagination"><span>{{ queried ? '查询结果' : `每页 20 条 · 第 ${offset/20+1} 页` }}</span><div><button class="secondary" :disabled="queried || offset===0 || loading" @click="page(-1)">上一页</button><button class="secondary" :disabled="!hasNext || loading" @click="page(1)">下一页</button></div></div></div><div v-if="showForm" class="overlay" @click.self="showForm=false"><section class="dialog" role="dialog" aria-modal="true" :aria-label="`${editing?'编辑':'新建'}${title}`"><div class="dialog-head"><h2>{{ editing?'编辑':'新建' }}{{ title }}</h2><button class="close" aria-label="关闭" @click="showForm=false">×</button></div><form @submit.prevent="save"><label>{{ title }}名称<input v-model="form.name" maxlength="120" required placeholder="请输入名称"></label><label v-if="kind==='merchant'">商户描述<textarea v-model="form.description" maxlength="500" rows="3" placeholder="请输入商户描述（选填）"></textarea></label><template v-else><label v-if="!editing">所属商户编号<input v-model="form.merchant_id" type="number" min="1" required placeholder="请输入商户编号"></label><label>分类编号（选填）<input v-model="form.category_id" type="number" min="1" placeholder="请输入同一商户的分类编号"></label><label>价格（元）<input v-model="form.price" type="number" min="0" step="0.01" required placeholder="请输入价格"></label></template><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="actions"><button type="button" class="secondary" @click="showForm=false">取消</button><button class="primary-btn" :disabled="saving">{{ saving?'保存中…':'保存' }}</button></div></form></section></div></section></template>
<style scoped>
